{
  "title": "A Slow Day Around Ubud",
  "summary": "A gentle day around Ubud with one rice terrace visit, a long vegan lunch and an easy temple stop kept free.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "p3",
      "note": "The one activity for today, kept slow and green. The sun won’t wait, so we start here before it gets hot."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch stays as planned. Take your time here, terima kasih (thank you) to the kitchen for the long pause."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A free temple stop to wind down the afternoon, easy on the budget and the feet."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner kept simple and cheap, a local plate to close the day."
    }
  ]
}

